-- Generated by `supabase@3.0.0 migration new target_reward_probability_five_percent`.
-- Target-only: new draws use 1% / 5% / 94%. Persisted rewards, totals, RPC
-- authorization, idempotency and the helper's existing private ACL stay intact.
CREATE OR REPLACE FUNCTION target_private.reward_points_for_roll(p_roll integer)
RETURNS integer LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
  SELECT CASE WHEN p_roll=0 THEN 10000 WHEN p_roll BETWEEN 1 AND 5 THEN 1000
    WHEN p_roll BETWEEN 6 AND 99 THEN 100 ELSE NULL END;
$$;
